	"TemplateId":"flx-cat-producto-cliente-list",
	"ObjectName":"CAT_Producto",
	"TypeId":"list",
	"Descrip":"Catálogo del cliente, con su precio de tarifa",
	"Body":"<div class=\"cli-cell col-2 col-l-3 col-m-4 col-s-6 padding-m\">\n',
N'  <div class=\"cli-card\">\n',
N'    <flx-navbutton class=\"cli-open\" type=\"openpage\" pagetypeid=\"view\" objectname=\"CAT_Producto\" objectwhere=\"(Productos.IdProducto=''{{IdProducto}}'')\" targetid=\"modal\">\n',
N'      <img is=\"flx-img\" class=\"cli-photo\" src=\"{{ImagenPrincipal|isnull:,{{ImagenPrincipal|url}}}}\" alt=\"{{Nombre}}\" \/>\n',
N'      <div class=\"cli-band\">\n',
N'        <div class=\"cli-cat\">{{Familia}} · {{Marca}}<\/div>\n',
N'        <div class=\"cli-name\">{{Nombre}}<\/div>\n',
N'        <div class=\"cli-foot\">\n',
N'          <span class=\"cli-price\">{{PrecioCliente|decimal:2}} €<\/span>\n',
N'          {{EstadoCodigo|switch:[sinstock:<span class=\"flx-state-danger\">{{translate|Sin stock}}<\/span>,novedad:<span class=\"flx-state-tools\">{{translate|Novedad}}<\/span>,oferta:<span class=\"flx-state-warning\">{{translate|Oferta}}<\/span>,else:]}}\n',
N'        <\/div>\n',
N'      <\/div>\n',
N'    <\/flx-navbutton>\n',
N'    <div class=\"cli-cmp-wrap\">\n',
N'      <input type=\"checkbox\" class=\"cli-cmp-chk\" data-idproducto=\"{{IdProducto}}\" onchange=\"cliCompareToggle(this)\" title=\"{{translate|Comparar}}\" \/>\n',
N'    <\/div>\n',
N'    <button type=\"button\" class=\"cli-fav {{EsFavorito|switch:[1:cli-fav-on,else:]}}\" data-idproducto=\"{{IdProducto}}\" onclick=\"cliToggleFavorito(this)\" title=\"{{translate|Favorito}}\">{{EsFavorito|switch:[1:&#9733;,else:&#9734;]}}<\/button>\n',
N'    <div class=\"cli-band\" style=\"padding-top:0\">\n',
N'      <button type=\"button\" class=\"cli-add\" data-idproducto=\"{{IdProducto}}\" data-variantes=''{{VariantesJson}}'' onclick=\"cliOpenAddPopup(this)\">{{translate|Añadir al carrito}}<\/button>\n',
N'    <\/div>\n',
N'  <\/div>\n',
N'<\/div>",
	"ViewName":"CAT_ProductoClienteList",
	"Header":"<style>\n',
N'  .cli-grid { display: flex; flex-flow: row wrap; }\n',
N'  .cli-cell { display: flex; }\n',
N'  .cli-card { position: relative; width: 100%; background: var(--module-color); border: 1px solid var(--border-module-color); border-radius: 12px; overflow: hidden; }\n',
N'  .cli-card:hover { border-color: var(--outstanding-color); }\n',
N'  .cli-open { display: block; cursor: pointer; }\n',
N'  .cli-photo { display: block; width: 100%; aspect-ratio: 1 \/ 1; object-fit: cover; border-bottom: 1px solid var(--border-module-color); background: light-dark(#f3f3f4, #292929); }\n',
N'  .cli-band { padding: 12px 16px; }\n',
N'  .cli-cat { font-size: 12px; color: light-dark(#555e6c, #a7b0bd); }\n',
N'  .cli-name { font-size: 14px; font-weight: 600; color: var(--txt-color); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n',
N'  .cli-foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: 8px; }\n',
N'  .cli-price { font-size: 16px; font-weight: 700; color: var(--txt-color); font-variant-numeric: tabular-nums; }\n',
N'  .cli-add { display: block; width: 100%; margin-top: 10px; padding: 7px 10px; border-radius: 8px; border: none; background: var(--outstanding-color); color: #fff; text-align: center; font-size: 13px; font-weight: 600; cursor: pointer; }\n',
N'  .cli-hide { display: none; }\n',
N'  .cli-cmp-wrap { position: absolute; top: 8px; left: 8px; z-index: 2; background: var(--module-color); border: 1px solid var(--border-module-color); border-radius: 6px; padding: 4px 6px; display: flex; align-items: center; }\n',
N'  .cli-cmp-chk { width: 16px; height: 16px; cursor: pointer; }\n',
N'  .cli-fav { position: absolute; top: 8px; right: 8px; z-index: 2; width: 30px; height: 30px; line-height: 28px; text-align: center; padding: 0; background: var(--module-color); border: 1px solid var(--border-module-color); border-radius: 8px; font-size: 16px; color: light-dark(#555e6c, #a7b0bd); cursor: pointer; }\n',
N'  .cli-fav-on { color: #e11d48; border-color: #e11d48; }\n',
N'  .cli-compare-bar { position: fixed; left: 50%; bottom: 24px; transform: translateX(-50%); z-index: 500; display: flex; align-items: center; gap: 12px; background: var(--module-color); border: 1px solid var(--border-module-color); border-radius: 12px; padding: 10px 18px; box-shadow: 0 6px 24px rgba(0,0,0,.18); }\n',
N'  .cli-compare-bar[hidden] { display: none; }\n',
N'  .cli-compare-bar span { font-size: 13px; color: var(--txt-color); }\n',
N'  .cli-compare-bar button { padding: 7px 14px; border-radius: 8px; border: none; font-size: 13px; font-weight: 600; cursor: pointer; }\n',
N'  .cli-compare-go { background: var(--outstanding-color); color: #fff; }\n',
N'  .cli-compare-clear { background: transparent; color: var(--txt-color); border: 1px solid var(--border-module-color) !important; }\n',
N'<\/style>\n',
N'<div class=\"cli-grid\">",
	"Footer":"<\/div>\n',
N'<div id=\"cli-compare-bar\" class=\"cli-compare-bar\" hidden>\n',
N'  <span><span id=\"cli-compare-count\">0<\/span> {{translate|productos seleccionados}}<\/span>\n',
N'  <button type=\"button\" class=\"cli-compare-go\" onclick=\"cliCompareGo()\">{{translate|Comparar}}<\/button>\n',
N'  <button type=\"button\" class=\"cli-compare-clear\" onclick=\"cliCompareClear()\">{{translate|Cancelar}}<\/button>\n',
N'<\/div>",
	"Empty":"<div style=\"text-align:center;padding:48px 16px;color:light-dark(#555e6c,#a7b0bd);\">{{translate|Todavía no hay productos en tu catálogo}}<\/div>",
